mapper.update:
update t_tag
set name = #{name,jdbcType=VARCHAR},
  create_user = #{createUser,jdbcType=INTEGER},
  create_time = #{createTime,jdbcType=TIMESTAMP},
  deleted = #{deleted,jdbcType=BIT}
where id = #{id,jdbcType=INTEGER}

mapper.select:
select count(1)
from t_tag
where deleted = 0
  and name = #{name}

    and id != #{excludeId}

select
  (
    select count(1)
    from t_question_tag qt
    inner join t_question q on q.id = qt.question_id and q.deleted = 0
    where qt.tag_id = #{tagId}
  )
  + (
    select count(1)
    from t_exam_paper_tag ept
    inner join t_exam_paper ep on ep.id = ept.exam_paper_id and ep.deleted = 0
    where ept.tag_id = #{tagId}
  )

select
from t_tag where id in
#{id}

select distinct t.id, t.name, t.create_user, t.create_time, t.deleted from t_tag t inner join t_question_tag qt on qt.tag_id = t.id inner join t_question q on q.id = qt.question_id and q.deleted = 0
and t.deleted = 0 and q.user_group_id = #{userGroupId}
and q.subject_id = #{subjectId}
and not exists ( select 1 from t_question_tag hidden_qt inner join t_tag hidden_t on hidden_t.id = hidden_qt.tag_id and hidden_t.deleted = 0 where hidden_qt.question_id = q.id and hidden_t.name = #{excludeTagName} )
and t.name like concat('%', #{keyword}, '%')
order by t.name asc, t.id asc
